// ("query" for search_memory, "feedback_content" for capture_feedback). v1.2
// emitted "memory_query"/"feedback_text" which mismatched ME handler validation
// and produced MISSING_REQUIRED_FIELDS at module dispatch.
// Preserves v1.2 extraction rules and v1.1 fail-closed semantics.
function safeNode(name) {
  try { const it = $(name).first(); return (it && it.json) ? it.json : {}; } catch (e) { return {}; }
}
const verify   = safeNode('PL_Verify_Context_Match');
const extract  = safeNode('PL_Extract_Planning_Input');
