// B11-PL: per-intent structured-field extraction from the user's goal text.
// Conservative — fills canonical module inputs when upstream didn't supply them.
function extractInputsForAction(action, goalText) {
  if (!goalText) return {};
  const g = String(goalText).trim();
  const lower = g.toLowerCase();

  if (action === 'create_task' || action === 'update_task' || action === 'complete_task' || action === 'delete_task') {
    return { description: g };
  }
  if (action === 'create_reminder' || action === 'update_reminder' || action === 'cancel_reminder') {
    const now = new Date();
    let dayOffset = 1; // default tomorrow
    if (/\bpoim[aâ]ine\b/.test(lower)) dayOffset = 2;
    else if (/\bm[aâ]ine\b/.test(lower)) dayOffset = 1;
    else if (/\bazi\b/.test(lower)) dayOffset = 0;
    let hh = 9, mm = 0;
    const hm = lower.match(/\b(?:la\s+ora\s+|la\s+|ora\s+)(\d{1,2})(?:[:\.h](\d{2}))?\b/);
    if (hm) {
      hh = Math.min(23, Math.max(0, Number(hm[1])));
      mm = hm[2] ? Math.min(59, Math.max(0, Number(hm[2]))) : 0;
    }
    const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + dayOffset, hh, mm, 0));
    const pad = (n) => String(n).padStart(2, '0');
    const iso = `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}T${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:00+00:00`;
    return { description: g, remind_at: iso };
  }
  if (action === 'list_tasks' || action === 'list_reminders') {
    return {};
  }
  if (action === 'search_memory') {
    let q = g;
    q = q.replace(/^\s*(?:cau?t[aăâ]|cautare|cauta)\s+(?:[îi]n\s+)?memorie?\s*/i, '');
    q = q.replace(/^\s*(?:pentru|despre)\s+/i, '');
    q = q.replace(/^\s*tot\s+ce\s+(?:stii|[ăa]i|stiu)\s+despre\s+/i, '');
    q = q.trim() || g;
    return { query: q };
  }
  if (action === 'capture_feedback') {
    let t = g;
    t = t.replace(/^\s*(?:sugestie|propunere|feedback)\s*[:\-–]\s*/i, '');
    t = t.replace(/^\s*(?:am\s+o\s+sugestie|am\s+o\s+propunere)\s*[:\-–]?\s*/i, '');
    t = t.trim() || g;
    return { feedback_content: t };
  }
  if (action === 'observe') {
